<script setup>
import{onMounted,reactive,ref}from'vue';import{request}from'../api';const periods=ref([]),summary=ref({}),error=ref('');const month=new Date().toISOString().slice(0,7);const form=reactive({employeeNo:'EMP-'+Date.now(),employeeName:'演示员工',period:month,scheduledMinutes:480});async function load(){[periods.value,summary.value]=await Promise.all([request(`/api/core/attendance/periods?period=${month}`),request(`/api/core/attendance/summary?period=${month}`)])}async function create(){try{await request('/api/core/attendance/periods',{method:'POST',body:JSON.stringify(form)});form.employeeNo='EMP-'+Date.now();await load()}catch(e){error.value=e.message}}async function act(p,a){try{let path=`/api/core/attendance/periods/${p.id}/${a}`,body;if(a==='work'){path=`/api/core/attendance/periods/${p.id}/entries`;body={idempotencyKey:crypto.randomUUID(),type:'WORK',minutes:p.scheduledMinutes,referenceNo:'CLOCK-'+Date.now()}}if(a==='approve'){path=`/api/admin/core/attendance/periods/${p.id}/approve`;body={remark:'主管复核通过'}}if(a==='close'){path=`/api/admin/core/attendance/periods/${p.id}/close`;body={payrollBatchNo:'PAY-'+month}}await request(path,{method:'POST',body:body?JSON.stringify(body):undefined});await load()}catch(e){error.value=e.message}}onMounted(load)
</script><template><section class="head"><div><span>TIME & ATTENDANCE</span><h3>{{month}} 考勤月结</h3><p>考勤流水、异常清零、职责分离审批与薪资批次锁定。</p></div><div class="metric"><b>{{summary.employees||0}}</b><small>员工</small><b>{{summary.openExceptions||0}}</b><small>异常</small></div></section><p class="err" v-if="error">{{error}}</p><form class="create" @submit.prevent="create"><input v-model="form.employeeNo"><input v-model="form.employeeName"><input v-model.number="form.scheduledMinutes" type="number"><button>建立月度台账</button></form><section class="table"><table><thead><tr><th>员工</th><th>应出勤</th><th>实际出勤</th><th>假期/加班</th><th>异常</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="p in periods" :key="p.id"><td><b>{{p.employeeName}}</b><small>{{p.employeeNo}}</small></td><td>{{p.scheduledMinutes}}</td><td>{{p.workedMinutes}}</td><td>{{p.approvedLeaveMinutes}} / {{p.approvedOvertimeMinutes}}</td><td>{{p.openExceptions}}</td><td>{{p.status}}</td><td><button v-if="p.status==='DRAFT'&&p.workedMinutes===0" @click="act(p,'work')">登记出勤</button><button v-if="p.status==='DRAFT'" @click="act(p,'submit')">提交</button><button v-if="p.status==='SUBMITTED'" @click="act(p,'approve')">审批</button><button v-if="p.status==='APPROVED'" @click="act(p,'close')">月结</button></td></tr></tbody></table></section></template>
<style scoped>.head,.create,.table{background:#fff;border:1px solid #dce2df;margin-top:20px;padding:24px}.head{display:flex;justify-content:space-between}.head span{font-size:11px;letter-spacing:.15em;color:#a56c24}.head h3{margin:6px 0}.head p{margin:0;color:#68777c}.metric{display:grid;grid-template-columns:auto auto;gap:3px 12px}.metric b{font-size:24px}.create{display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:10px}.create input{padding:10px;border:1px solid #ccd6d2}.create button,.table button{border:0;background:#235a74;color:white;padding:8px 10px;margin:2px}.table{overflow:auto}.table small{display:block;color:#68777c}.err{color:#a03f38}@media(max-width:800px){.create{grid-template-columns:1fr}.metric{display:none}}</style>
